import json

# New hypothesis: Create a complete/dense shape by filling all gaps
# Make every row fully connected from first to last non-zero element

def make_rows_connected(grid):
    result = []
    for row in grid:
        nonzero_cols = [c for c, v in enumerate(row) if v != 0]
        if nonzero_cols:
            # Fill everything between min and max non-zero col
            new_row = list(row)
            for c in range(min(nonzero_cols), max(nonzero_cols) + 1):
                new_row[c] = 2
            result.append(new_row)
        else:
            result.append(row)  # Empty stays empty
    return result

