import json

# Hypothesis: Create a perfect triangular pyramid by completing missing cells
# Based on the structure, fill all cells that should be part of the connected shape

# Start with current and add cells that connect disconnected components
def complete_shape(grid):
    result = [row[:] for row in grid]

    # Iteratively add missing connections until stable
    changed = True
    while changed:
        changed = False
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == 0:
                    # Check if adding this cell connects two existing parts
                    neighbors = [
                        (r-1, c), (r+1, c), (r, c-1), (r, c+1)
                    ]
                    has_connected_neighbors = False
                    for nr, nc in neighbors:
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] != 0:
                                has_connected_neighbors = True
                                break
                    if has_connected_neighbors:
                        result[r][c] = 2
                        changed = True

    return result

